// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(sender != c.owner());
        vm.deal(sender, amount);
        vm.prank(sender);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "withdraw from non-owner must revert");
    }
}
